const b = $input.first().json.body || {};
const c = b.datos || {};
const sd = $getWorkflowStaticData('global');
sd.cupones = sd.cupones || [];
if (b.evento_id && sd.cupones.includes(b.evento_id)) return [];
if (b.evento_id) sd.cupones = [...sd.cupones, b.evento_id].slice(-100);

const money = (n) => new Intl.NumberFormat('es-AR', { style: 'currency', currency: 'ARS' }).format(n || 0);
const que = c.tipo === 'porcentaje' ? `${c.valor}% de descuento` : `${money(c.valor)} de descuento`;
const minimo = c.min_compra ? ` en compras desde ${money(c.min_compra)}` : '';
const vence = c.vence_at ? new Date(c.vence_at).toLocaleDateString('es-AR') : '';
return [{ json: { oferta: {
  titulo: `Cupón ${c.codigo}: ${que}`,
  lineas: [`Usá el cupón ${c.codigo} y obtené ${que}${minimo}.`].concat(vence ? [`Válido hasta el ${vence}.`] : []),
  url: c.tienda_url || 'https://hefestotech.vercel.app',
} } }];

// Compara las ofertas vigentes con las ya avisadas. La primera corrida solo
// memoriza (no manda las ofertas que ya existían).
const sd = $getWorkflowStaticData('global');
const previas = sd.productos || {};
const vigentes = {};
const nuevos = [];
for (const it of $input.all()) {
  const p = it.json;
  if (!p || !p.id) continue;
  const firma = `${p.descuento_porcentaje}|${p.precio_con_descuento}`;
  vigentes[p.id] = firma;
  if (previas[p.id] !== firma) nuevos.push(p);
}
const primera = !sd.inicializado;
sd.productos = vigentes;
sd.inicializado = true;
if (primera || !nuevos.length) return [];

const money = (n) => new Intl.NumberFormat('es-AR', { style: 'currency', currency: 'ARS' }).format(n || 0);
const top = nuevos.sort((a, b) => b.descuento_porcentaje - a.descuento_porcentaje).slice(0, 8);
return [{ json: { oferta: {
  titulo: nuevos.length === 1 ? `Oferta: ${top[0].nombre}` : `${nuevos.length} productos en oferta`,
  lineas: top.map(p => `${p.nombre}: ${Math.round(p.descuento_porcentaje)}% OFF (ahora ${money(p.precio_con_descuento)})`),
  url: 'https://hefestotech.vercel.app',
} } }];

const oferta = $('Oferta lista').first().json.oferta;
const esc = (s) => String(s).replace(/[&<>"]/g, ch => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;' }[ch]));
const lineas = oferta.lineas.map(l => `<li>${esc(l)}</li>`).join('');
const html = `<div style="font-family:Arial,sans-serif;max-width:560px;margin:0 auto;color:#1b1f24">` +
  `<h2>🔥 ${esc(oferta.titulo)}</h2><ul>${lineas}</ul>` +
  `<p style="margin:20px 0"><a href="${esc(oferta.url)}" style="background:#0a7fb8;color:#fff;padding:10px 18px;border-radius:8px;text-decoration:none">Ver en la tienda</a></p>` +
  `<p style="color:#6b7280;font-size:12px">Recibís este mail porque te suscribiste al newsletter de HefestoTech. ` +
  `Si no querés recibir más, respondé este correo con la palabra BAJA.</p></div>`;
return $input.all()
  .filter(it => it.json.email && String(it.json.email).includes('@'))
  .map(it => ({ json: { to_email: it.json.email, subject: `🔥 ${oferta.titulo} | HefestoTech`, html } }));
